    @Override public void onCreate(Bundle b){super.onCreate(b);if(!Ui.allow(this))return;if(b!=null){tab=b.getInt("tab",0);profileView=b.getBoolean("profile",false);selectedSource=b.getString("source","yoru");if(selectedSource.equals("all"))selectedSource="yoru";query=b.getString("query","");bucket=b.getString("bucket","");int[] saved=b.getIntArray("scroll");if(saved!=null)System.arraycopy(saved,0,scrollState,0,Math.min(saved.length,scrollState.length));}root=Ui.base(this);header=Ui.row(this);header.setPadding(Ui.dp(this,18),Ui.dp(this,13),Ui.dp(this,18),Ui.dp(this,13));ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_yoru);header.addView(logo,Ui.lp(this,36,36));TextView brand=Ui.text(this,"YORU.",25,Ui.TEXT,true);LinearLayout.LayoutParams bp=Ui.lp(this,0,-2);bp.weight=1;bp.leftMargin=Ui.dp(this,9);header.addView(brand,bp);Ui.gap(header,Ui.iconButton(this,"search","Найти аниме",()->{profileView=false;tab=1;render();search.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,InputMethodManager.SHOW_IMPLICIT);}),38,38,0);Ui.gap(header,Ui.iconButton(this,"settings","Настройки",()->{profileView=true;render();}),38,38,8);root.addView(header,Ui.lp(this,-1,-2));content=new FrameLayout(this);root.addView(content,new FrameLayout.LayoutParams(-1,0,1));bottom=Ui.row(this);bottom.setPadding(Ui.dp(this,9),Ui.dp(this,5),Ui.dp(this,9),Ui.dp(this,5));bottom.setBackground(Ui.shape(Ui.SURFACE,0,this));root.addView(bottom,Ui.lp(this,-1,64));if(getIntent().getBooleanExtra("openDownloads",false)){tab=3;profileView=false;}String genreExtra=getIntent().getStringExtra("genreId");if(genreExtra!=null&&!genreExtra.isEmpty()){filter=new ApiRepository.Filter();filter.genre=genreExtra;tab=1;profileView=false;}render();}
