    private Anime dailyHero(){ArrayList<Anime> pool=new ArrayList<>(topRows);if(pool.isEmpty())pool=YoruApp.app().api.seed();if(pool.isEmpty())pool.add(seedFallback());ArrayList<Anime> vis=YoruBrain.visible(pool);if(!vis.isEmpty())pool=vis;Calendar c=Calendar.getInstance();int day=c.get(Calendar.DAY_OF_YEAR)+c.get(Calendar.YEAR)*3;pool.sort((a,b)->Double.compare(b.score,a.score));int idx=Math.floorMod(day*31+day/7,Math.max(1,pool.size()));return pool.get(idx);}
    private Anime seedFallback(){Anime a=new Anime();a.source="yoru";a.id="52991";a.malId=52991;a.title="Провожающая в последний путь Фрирен";a.original="Sousou no Frieren";a.poster="https://anilibria.top/storage/releases/posters/9542/8UGD4dHHp1kdjquBph2CUSk9pLNsGtYw.webp";a.year=2023;a.type="ТВ";a.status="released";a.episodes=28;a.score=9.1;return a;}
    private void appendTop(){if(topLoading)return;if(topShown<topRows.size()){int from=topShown,to=Math.min(topRows.size(),topShown+6);topShown=to;addCardRows(topHost,topRows.subList(from,to));if(topShown>=topRows.size()&&topMore)loadTop(false);return;}if(topMore)loadTop(false);}
    private void loadTop(boolean reset){if(topLoading)return;topLoading=true;final int gen=generation;final int requested=reset?1:topPage+1;uiTask(()->{try{ApiRepository.Filter f=new ApiRepository.Filter();f.sort="RATING_DESC";Anime.Page p=YoruApp.app().api.catalog("shikimori","",requested,f);YoruApp.app().main.post(()->{topLoading=false;if(gen!=generation||isFinishing())return;if(reset){topRows.clear();topShown=0;if(topHost!=null)topHost.removeAllViews();}topPage=requested;topMore=p.more;HashSet<String> ids=new HashSet<>();for(Anime a:topRows)ids.add(a.key());for(Anime a:p.items)if(Anime.valid(a)&&YoruBrain.visible(a)&&ids.add(a.key()))topRows.add(a);if(topHost!=null){int to=Math.min(topRows.size(),topShown+6);if(to>topShown){addCardRows(topHost,topRows.subList(topShown,to));topShown=to;}}if(homeSwipe!=null)homeSwipe.setRefreshing(false);});}catch(Exception e){YoruApp.app().main.post(()->{topLoading=false;if(homeSwipe!=null)homeSwipe.setRefreshing(false);});}});}
    private void refreshHome(boolean manual){lastAutoRefresh=System.currentTimeMillis();if(manual&&homeSwipe!=null)homeSwipe.setRefreshing(true);loadTop(true);}
    private void addCardRows(LinearLayout host,List<Anime> list){int cols=getResources().getConfiguration().screenWidthDp>=650?3:2;for(int i=0;i<list.size();i+=cols){LinearLayout row=Ui.row(this);row.setGravity(Gravity.TOP);for(int k=0;k<cols;k++){if(i+k<list.size()){Ui.Card c=new Ui.Card(this,(getResources().getConfiguration().screenWidthDp/cols-25)*3/2);c.bind(list.get(i+k));row.addView(c,new LinearLayout.LayoutParams(0,-2,1));}else row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}host.addView(row);}ArrayList<Anime> warm=new ArrayList<>(list.subList(0,Math.min(6,list.size())));if(!warm.isEmpty())YoruApp.app().discovery.execute(()->{try{YoruApp.app().api.prefetchQuickDetails(warm,warm.size());}catch(Exception ignored){}});}

