    private void catalogue(){LinearLayout col=Ui.column(this);col.setPadding(Ui.dp(this,15),Ui.dp(this,8),Ui.dp(this,15),0);content.addView(col,new FrameLayout.LayoutParams(-1,-1));LinearLayout titleRow=Ui.row(this);titleRow.addView(Ui.text(this,"Каталог",27,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));col.addView(titleRow);Ui.space(col,13);LinearLayout searchRow=Ui.row(this);search=new EditText(this);search.setTextColor(Ui.TEXT);search.setHintTextColor(Ui.MUTED);search.setSingleLine();search.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(150)});search.setTextSize(14*YoruApp.app().store.fontScale()/100f);search.setTypeface(Ui.typeface(this,false));search.setHint("Найти аниме или озвучку");search.setText(query);search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);search.setPadding(Ui.dp(this,14),0,Ui.dp(this,14),0);search.setBackground(Ui.stroke(Ui.CARD,13,this));searchRow.addView(search,new LinearLayout.LayoutParams(0,Ui.dp(this,48),1));Ui.gap(searchRow,Ui.iconButton(this,"close","Очистить поиск",()->{query="";if(searchTask!=null)handler.removeCallbacks(searchTask);search.setText("");renderSearchPanel();loadCatalog(true);search.requestFocus();}),44,44,8);Ui.gap(searchRow,Ui.iconButton(this,"filter","Фильтры",this::filters),44,44,8);col.addView(searchRow);searchPanel=Ui.column(this);col.addView(searchPanel);renderSearchPanel();catalogChips(col);Ui.space(col,10);LinearLayout voiceLine=Ui.row(this);String chosenVoice=YoruApp.app().store.onlyPreferredVoice()?ApiRepository.voiceTitle(YoruApp.app().store.voicePreference()):YoruApp.app().store.favoriteVoiceSummary();if(chosenVoice.isEmpty())chosenVoice="Авто";voiceLine.addView(Ui.text(this,"Озвучки: "+chosenVoice+(YoruApp.app().store.onlyPreferredVoice()?" · только выбранная":""),11,Ui.MUTED,false),new LinearLayout.LayoutParams(0,-2,1));TextView tune=Ui.chip(this,"Настроить",false,this::playbackSettings);voiceLine.addView(tune,Ui.lp(this,-2,-2));col.addView(voiceLine,Ui.lp(this,-1,-2));selectedSource="yoru";summary=Ui.text(this,"",11,Ui.MUTED,false);summary.setPadding(0,Ui.dp(this,13),0,Ui.dp(this,10));col.addView(summary);grid=new GridView(this);grid.setNumColumns(getResources().getConfiguration().screenWidthDp>=650?3:2);grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setVerticalSpacing(Ui.dp(this,9));grid.setHorizontalSpacing(Ui.dp(this,5));grid.setClipToPadding(false);grid.setPadding(0,0,0,Ui.dp(this,15));adapter=new CatalogAdapter();grid.setAdapter(adapter);col.addView(grid,new LinearLayout.LayoutParams(-1,0,1));grid.setOnScrollListener(new AbsListView.OnScrollListener(){public void onScrollStateChanged(AbsListView v,int state){}public void onScroll(AbsListView v,int first,int count,int total){if(total>0&&more&&!loading&&first+count>=total-6)loadCatalog(false);}});search.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_SEARCH||(event!=null&&event.getKeyCode()==KeyEvent.KEYCODE_ENTER&&event.getAction()==KeyEvent.ACTION_UP)){submitSearch(true);return true;}return false;});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString().trim().replaceAll("\\s+"," ");renderSearchPanel();if(searchTask!=null)handler.removeCallbacks(searchTask);searchTask=()->{loadCatalog(true);};handler.postDelayed(searchTask,query.isEmpty()?120:260);}public void afterTextChanged(Editable e){}});loadCatalog(true);}
