    private void submitSearch(boolean remember){if(searchTask!=null)handler.removeCallbacks(searchTask);query=search==null?query:search.getText().toString().trim().replaceAll("\\s+"," ");if(remember)YoruApp.app().store.addSearch(query);renderSearchPanel();loadCatalog(true);InputMethodManager imm=(InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(imm!=null&&search!=null)imm.hideSoftInputFromWindow(search.getWindowToken(),0);}
    private void renderSearchPanel(){if(searchPanel==null)return;searchPanel.removeAllViews();String q=query==null?"":query.trim();if(q.isEmpty()){List<String> rows=YoruApp.app().store.searchHistory();if(rows.isEmpty())return;Ui.space(searchPanel,10);LinearLayout head=Ui.row(this);head.addView(Ui.text(this,"История поиска",12,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));TextView clear=Ui.text(this,"Очистить",10,Ui.PURPLE,true);clear.setPadding(Ui.dp(this,8),Ui.dp(this,6),0,Ui.dp(this,6));clear.setOnClickListener(v->{YoruApp.app().store.clearSearchHistory();renderSearchPanel();});head.addView(clear);searchPanel.addView(head);Ui.space(searchPanel,8);LinearLayout list=Ui.column(this);int shown=0;for(String item:rows){if(shown>=6)break;ArrayList<Anime> match=localSuggestions(item);Anime cover=match.isEmpty()?null:match.get(0);list.addView(historyRow(item,cover),Ui.lp(this,-1,-2));Ui.space(list,6);shown++;}searchPanel.addView(list,Ui.lp(this,-1,-2));return;}ArrayList<Anime> suggestions=localSuggestions(q);if(suggestions.isEmpty())return;Ui.space(searchPanel,10);searchPanel.addView(Ui.text(this,"Найдено рядом",12,Ui.TEXT,true));Ui.space(searchPanel,8);LinearLayout list=Ui.column(this);int index=0;for(Anime a:suggestions.subList(0,Math.min(5,suggestions.size()))){LinearLayout row=suggestionRow(a);list.addView(row,Ui.lp(this,-1,-2));row.setAlpha(0f);row.setTranslationY(Ui.dp(this,8));row.animate().alpha(1f).translationY(0).setStartDelay(index*45L).setDuration(170).start();Ui.space(list,6);index++;}searchPanel.addView(list,Ui.lp(this,-1,-2));}
    private LinearLayout suggestionRow(Anime a){LinearLayout row=Ui.row(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(this,10),Ui.dp(this,8),Ui.dp(this,11),Ui.dp(this,8));row.setBackground(Ui.stroke(Ui.SURFACE,12,this));ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(Ui.shape(Ui.CARD,10,this));image.setClipToOutline(true);row.addView(image,Ui.lp(this,40,56));YoruApp.app().images.load(image,a);LinearLayout txt=Ui.column(this);txt.setPadding(Ui.dp(this,11),0,0,0);TextView name=Ui.text(this,YoruBrain.title(a),13,Ui.TEXT,true);name.setMaxLines(1);name.setEllipsize(TextUtils.TruncateAt.END);txt.addView(name);Ui.space(txt,4);String meta=(a.year>0?String.valueOf(a.year):"")+(a.score>0?" · ★ "+String.format(Locale.US,"%.2f",a.score):"");txt.addView(Ui.text(this,meta.isEmpty()?YoruBrain.chip(a):meta,10,Ui.PURPLE,false));row.addView(txt,new LinearLayout.LayoutParams(0,-2,1));Ui.press(row);row.setOnClickListener(v->{YoruApp.app().store.addSearch(query);Ui.openDetails(this,a);});return row;}
    private LinearLayout historyRow(String item,Anime cover){LinearLayout row=Ui.row(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(this,10),Ui.dp(this,7),Ui.dp(this,11),Ui.dp(this,7));row.setBackground(Ui.stroke(Ui.SURFACE,11,this));ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(Ui.shape(Ui.CARD,9,this));image.setClipToOutline(true);row.addView(image,Ui.lp(this,30,42));if(cover!=null)YoruApp.app().images.load(image,cover);else image.setImageResource(R.drawable.ic_yoru);TextView name=Ui.text(this,item,12,Ui.TEXT,false);name.setMaxLines(1);name.setEllipsize(TextUtils.TruncateAt.END);name.setPadding(Ui.dp(this,10),0,0,0);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon icon=new Ui.Icon(this,"history");icon.color=Ui.MUTED;row.addView(icon,Ui.lp(this,18,18));Ui.press(row);row.setOnClickListener(v->{query=item;search.setText(item);search.setSelection(search.length());submitSearch(false);});return row;}
    private ArrayList<Anime> localCatalogPreview(String source,ApiRepository.Filter f){ArrayList<Anime> out=new ArrayList<>();for(Anime a:YoruApp.app().api.seed())if(Anime.valid(a)&&YoruBrain.visible(a)&&localFilter(a,f))out.add(a);out.sort((a,b)->localCompare(a,b,f));return new ArrayList<>(out.subList(0,Math.min(24,out.size())));}
    private boolean localFilter(Anime a,ApiRepository.Filter f){if(f==null)return true;if(!f.year.isEmpty()&&a.year!=parseInt(f.year))return false;if(!f.type.isEmpty()){String t=(a.type==null?"":a.type).toLowerCase(Locale.ROOT);if(f.type.equals("MOVIE")&&!t.contains("movie")&&!t.contains("фильм"))return false;if(f.type.equals("TV")&&!t.contains("tv")&&!t.contains("тв")&&!t.contains("сериал"))return false;}if(!f.status.isEmpty()){String st=a.statusLabel().toLowerCase(Locale.ROOT);if(f.status.equals("ongoing")&&!st.contains("онго"))return false;if(f.status.equals("released")&&!st.contains("закон"))return false;if(f.status.equals("anons")&&!st.contains("анонс"))return false;}if(!f.genre.isEmpty()){String g=String.join(" ",a.genres).toLowerCase(Locale.ROOT);String want=Genres.nameById(f.genre).toLowerCase(Locale.ROOT);if(!want.isEmpty()&&!g.contains(want))return false;}return true;}
    private int localCompare(Anime a,Anime b,ApiRepository.Filter f){if(f!=null&&"NAME".equals(f.sort))return YoruBrain.title(a).compareToIgnoreCase(YoruBrain.title(b));return Integer.compare(localSortScore(b,f),localSortScore(a,f));}
    private int localSortScore(Anime a,ApiRepository.Filter f){String sort=f==null?"":f.sort;if("NAME".equals(sort))return -YoruBrain.title(a).toLowerCase(Locale.ROOT).hashCode();int r=0;if("YEAR_DESC".equals(sort))r+=Math.max(0,a.year)*100;else r+=(int)Math.round(a.score*1000);if(a.ongoing())r+=80;return r;}
    private int parseInt(String v){try{return Integer.parseInt(v);}catch(Exception e){return 0;}}
    private ArrayList<Anime> localSuggestions(String q){LinkedHashMap<String,Anime> found=new LinkedHashMap<>();String needle=ApiRepository.plainName(q);if(needle.length()<1)return new ArrayList<>();ArrayList<Anime> pool=new ArrayList<>();pool.addAll(YoruApp.app().store.recent());pool.addAll(YoruApp.app().store.favorites());pool.addAll(YoruApp.app().api.seed());pool.addAll(topRows);for(Anime a:pool){if(!Anime.valid(a)||!YoruBrain.visible(a)||found.containsKey(a.key()))continue;String hay=ApiRepository.plainName(a.title+" "+a.original+" "+a.alias+" "+String.join(" ",a.genres)+" "+YoruApp.app().store.note(a)+" "+YoruApp.app().store.tags(a));if(hay.contains(needle))found.put(a.key(),a);}ArrayList<Anime> out=new ArrayList<>(found.values());out.sort((a,b)->Integer.compare(searchRank(b,needle),searchRank(a,needle)));return new ArrayList<>(out.subList(0,Math.min(10,out.size())));}
    private int searchRank(Anime a,String needle){String title=ApiRepository.plainName(a.title),orig=ApiRepository.plainName(a.original),all=ApiRepository.plainName(a.title+" "+a.original+" "+a.alias);int r=0;if(title.equals(needle)||orig.equals(needle))r+=10000;else if(title.startsWith(needle)||orig.startsWith(needle))r+=6500;else if(all.contains(needle))r+=3000;r+=Math.max(0,Math.min(3000,a.year));if(a.ongoing())r+=200;if(a.score>0)r+=(int)(a.score*20);return r;}
    private void catalogueReplace(){invalidateScreen(1);content.removeAllViews();loading=false;catalogue();capture(1,screenKey(1));}
    private void loadCatalog(boolean reset){if(adapter==null||summary==null)return;if(reset&&catalogFuture!=null&&!catalogFuture.isDone()){catalogFuture.cancel(true);loading=false;}if(loading&&!reset)return;String q=query==null?"":query.trim().replaceAll("\\s+"," ");query=q;String source=selectedSource;ApiRepository.Filter f=filter;if(screenCache[1]!=null)screenKeys[1]=screenKey(1);if(reset){generation++;pageNumber=0;catalog.clear();more=false;if(q.length()>=1)catalog.addAll(localSuggestions(q));else catalog.addAll(localCatalogPreview(source,filter));adapter.notifyDataSetChanged();}loading=true;int gen=generation,requested=pageNumber+1;summary.setOnClickListener(null);summary.setText(reset?(catalog.isEmpty()?"":""):"Ещё аниме…");catalogFuture=uiTask(()->{try{if(Thread.currentThread().isInterrupted())return;Anime.Page p=YoruApp.app().api.catalog(source,q,requested,f);if(Thread.currentThread().isInterrupted())return;YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;pageNumber=requested;more=p.more;HashSet<String> ids=new HashSet<>();if(reset&&!p.items.isEmpty())catalog.clear();for(Anime a:catalog)ids.add(a.key());for(Anime a:p.items)if(YoruBrain.visible(a)&&ids.add(a.key()))catalog.add(a);adapter.notifyDataSetChanged();String prefix=p.total>=0?"Найдено: "+p.total+" · ":q.isEmpty()&&YoruApp.app().api.countOf(source)>0?"В базе: "+YoruApp.app().api.countOf(source)+" · ":"";if(p.note!=null&&!p.note.isEmpty())prefix=p.note+" · "+prefix;summary.setText(prefix+"Показано: "+catalog.size()+(p.more?" · листайте дальше":""));if(catalog.isEmpty())summary.setText(q.isEmpty()?"Пока пусто. Потяните вниз или вернитесь позже.":"Ничего не найдено. Попробуйте другое название.");});}catch(Exception e){YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;more=false;if(catalog.isEmpty()&&source.equals("anilibria")&&q.isEmpty())catalog.addAll(YoruApp.app().api.seed());adapter.notifyDataSetChanged();summary.setText(catalog.isEmpty()?"Подборка пока не получена. Потяните вниз для обновления.":"Показано: "+catalog.size()+" · данные могли устареть");summary.setOnClickListener(v->loadCatalog(true));});}});if(catalogFuture.isCancelled()){loading=false;summary.setText("Очередь занята. Повторите чуть позже.");summary.setOnClickListener(v->loadCatalog(true));}}
    private final class CatalogAdapter extends BaseAdapter {public int getCount(){return catalog.size();}public Object getItem(int p){return catalog.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,android.view.ViewGroup parent){int cols=getResources().getConfiguration().screenWidthDp>=650?3:2;Ui.Card card=old instanceof Ui.Card?(Ui.Card)old:new Ui.Card(MainActivity.this,(getResources().getConfiguration().screenWidthDp/cols-23)*3/2);card.bind(catalog.get(p));return card;}}
    private void filters(){String filterSource=(selectedSource.equals("shikimori")||selectedSource.equals("yummy")||selectedSource.equals("anilibria"))?selectedSource:"shikimori";LinearLayout c=Ui.column(this);c.setPadding(Ui.dp(this,4),0,Ui.dp(this,4),0);String[][] genreItems=Genres.all(filterSource);String[] genreLabels=new String[genreItems.length],genreIds=new String[genreItems.length];for(int gi=0;gi<genreItems.length;gi++){genreIds[gi]=genreItems[gi][0];genreLabels[gi]=genreItems[gi][1];}Spinner genre=spinner(c,"Жанр",genreLabels,Arrays.asList(genreIds).indexOf(filter.genre));ArrayList<String> ys=new ArrayList<>();ys.add("Все годы");for(int y=Calendar.getInstance().get(Calendar.YEAR)+1;y>=1970;y--)ys.add(String.valueOf(y));Spinner year=spinner(c,"Год",ys.toArray(new String[0]),filter.year.isEmpty()?0:ys.indexOf(filter.year));String[] kinds={"Любой формат","ТВ","Фильм","ONA","OVA","Спешл"},values={"","TV","MOVIE","ONA","OVA","SPECIAL"};Spinner type=spinner(c,"Формат",kinds,Arrays.asList(values).indexOf(filter.type));String[] statusLabels={"Любой статус","Выходит","Завершён","Анонс"},statusValues={"","ongoing","released","anons"};Spinner status=spinner(c,"Статус",statusLabels,Arrays.asList(statusValues).indexOf(filter.status));String[] sortLabels={"По рейтингу","Популярные","Сначала новые","По алфавиту"},sortValues={"RATING_DESC","POPULARITY","YEAR_DESC","NAME"};Spinner sort=spinner(c,"Порядок",sortLabels,Arrays.asList(sortValues).indexOf(filter.sort));Ui.customX(this,"Фильтры каталога",c,"Применить",()->{ApiRepository.Filter f=new ApiRepository.Filter();f.genre=genreIds[genre.getSelectedItemPosition()];f.year=year.getSelectedItemPosition()==0?"":ys.get(year.getSelectedItemPosition());f.type=values[type.getSelectedItemPosition()];f.status=statusValues[status.getSelectedItemPosition()];f.sort=sortValues[sort.getSelectedItemPosition()];filter=f;invalidateScreen(1);loadCatalog(true);},"Сбросить",()->{filter=new ApiRepository.Filter();invalidateScreen(1);loadCatalog(true);});}
    private Spinner spinner(LinearLayout col,String title,String[] values,int initial){col.addView(Ui.text(this,title,11,Ui.MUTED,false));Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);s.setSelection(Math.max(0,initial));col.addView(s,Ui.lp(this,-1,45));Ui.space(col,8);return s;}
