    private void settings(){String[] choices={"Просмотр","Внешний вид","О проекте"};Ui.choices(this,"YORU",choices,i->{switch(i){case 0:playbackSettings();break;case 1:appearanceSettings();break;default:aboutDialog();break;}});}
    private void profileAction(String action){if(action.equals("playback")){playbackSettings();return;}if(action.equals("appearance")){appearanceSettings();return;}if(action.equals("queue")){FeaturePanels.queue(this);return;}if(action.equals("smart")){FeaturePanels.smart(this);return;}if(action.equals("insights")){FeaturePanels.stats(this);return;}aboutDialog();}
    private void appearanceSettings(){SecureStore store=YoruApp.app().store;LinearLayout col=Ui.column(this);col.setPadding(Ui.dp(this,4),0,Ui.dp(this,4),0);FrameLayout preview=new FrameLayout(this);preview.setBackground(Ui.shape(Ui.BG,16,this));preview.setClipToOutline(true);ImageView wallPreview=new ImageView(this);wallPreview.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.addView(wallPreview,new FrameLayout.LayoutParams(-1,-1));LinearLayout sample=Ui.column(this);sample.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14));sample.addView(Ui.text(this,"Так выглядит YORU",14,Ui.TEXT,true));Ui.space(sample,8);sample.addView(Ui.chip(this,"Карточка",true,null),Ui.lp(this,-2,-2));Ui.space(sample,8);sample.addView(Ui.text(this,"Текст и панели остаются читаемыми.",11,Ui.MUTED,false));preview.addView(sample,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));col.addView(preview,Ui.lp(this,-1,190));File wallFile=new File(getFilesDir(),"yoru-wallpaper.jpg");Bitmap wallBitmap=wallFile.exists()?BitmapFactory.decodeFile(wallFile.getAbsolutePath()):null;if(wallBitmap!=null)wallPreview.setImageBitmap(wallBitmap);final boolean[] hasWall={wallBitmap!=null};Switch wall=new Switch(this);wall.setText("Свои обои из Google Фото или галереи");wall.setTextColor(Ui.TEXT);wall.setTextSize(13);wall.setTypeface(Ui.typeface(this,false));wall.setChecked(store.wallpaperOn()&&hasWall[0]);col.addView(wall,Ui.lp(this,-1,50));col.addView(Ui.button(this,"Выбрать изображение",false,()->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("image/*");startActivityForResult(pick,104);}),Ui.lp(this,-1,-2));Ui.space(col,8);TextView scaleLabel=Ui.text(this,"Масштаб обоев: "+store.wallpaperScale()+"%",12,Ui.MUTED,true);col.addView(scaleLabel);SeekBar scale=new SeekBar(this);scale.setMax(160);scale.setProgress(store.wallpaperScale()-100);col.addView(scale,Ui.lp(this,-1,42));scale.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){int value=100+p;scaleLabel.setText("Масштаб обоев: "+value+"%");wallPreview.setScaleX(value/100f);wallPreview.setScaleY(value/100f);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});wallPreview.setScaleX(store.wallpaperScale()/100f);wallPreview.setScaleY(store.wallpaperScale()/100f);Switch trans=new Switch(this);trans.setText("Прозрачный режим");trans.setTextColor(Ui.TEXT);trans.setTextSize(13);trans.setTypeface(Ui.typeface(this,false));trans.setChecked(store.transparent());col.addView(trans,Ui.lp(this,-1,50));TextView alphaLabel=Ui.text(this,"Прозрачность панелей: "+store.transparentAlpha()+"%",12,Ui.MUTED,true);col.addView(alphaLabel);SeekBar alpha=new SeekBar(this);alpha.setMax(80);alpha.setProgress(store.transparentAlpha()-20);col.addView(alpha,Ui.lp(this,-1,42));alpha.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){int value=20+p;alphaLabel.setText("Прозрачность панелей: "+value+"%");int a=(int)(255f*value/100f);android.graphics.drawable.Drawable d=sample.getBackground();if(d!=null)d.setAlpha(a);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});sample.setBackground(Ui.stroke(Ui.CARD,14,this));sample.getBackground().setAlpha((int)(255f*store.transparentAlpha()/100f));trans.setOnCheckedChangeListener((b,on)->{int a=on?(int)(255f*(20+alpha.getProgress())/100f):255;android.graphics.drawable.Drawable d=sample.getBackground();if(d!=null)d.setAlpha(a);});TextView previewNote=Ui.text(this,"Предпросмотр показывает, как обои и прозрачность будут выглядеть в разных вкладках.",10,Ui.MUTED,false);col.addView(previewNote);Ui.space(col,10);TextView size=Ui.text(this,"Размер текста: "+store.fontScale()+"%",12,Ui.MUTED,true);col.addView(size);SeekBar bar=new SeekBar(this);bar.setMax(45);bar.setProgress(store.fontScale()-85);col.addView(bar,Ui.lp(this,-1,42));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean f){int value=85+p;size.setText("Размер текста: "+value+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});Switch custom=new Switch(this);custom.setText("Использовать свой .ttf / .otf");custom.setTextColor(Ui.TEXT);custom.setTextSize(13);custom.setTypeface(Ui.typeface(this,false));custom.setChecked(store.customFont());col.addView(custom,Ui.lp(this,-1,50));TextView current=Ui.text(this,"Текущий шрифт: "+store.fontName(),11,Ui.MUTED,false);col.addView(current);Ui.space(col,10);col.addView(Ui.button(this,"Выбрать файл шрифта",false,()->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("*/*");pick.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"font/ttf","font/otf","application/x-font-ttf","application/x-font-otf","application/octet-stream"});startActivityForResult(pick,103);}));Ui.space(col,8);col.addView(Ui.text(this,"Файл копируется внутрь приложения. Можно выбрать шрифт из Google Files или любого проводника.",10,Ui.MUTED,false));Ui.custom(this,"Внешний вид",col,"Сохранить",()->{YoruApp.app().store.appearance(85+bar.getProgress(),custom.isChecked(),YoruApp.app().store.fontName());YoruApp.app().store.appearanceExtra(wall.isChecked()&&hasWall[0],100+scale.getProgress(),trans.isChecked(),20+alpha.getProgress());Ui.toast(this,"Внешний вид обновлён");recreateUi();},"Сбросить",()->{YoruApp.app().store.appearance(100,false,"Системный");YoruApp.app().store.appearanceExtra(false,100,false,70);Ui.toast(this,"Внешний вид сброшен");recreateUi();},"Отмена");}
    private void recreateUi(){invalidateScreen(0);invalidateScreen(1);invalidateScreen(2);invalidateScreen(3);invalidateScreen(4);render();}
    private void importWallpaper(Uri uri){Ui.Progress wait=Ui.progress(this,"Готовим обои…",false,null);YoruApp.app().io.execute(()->{try{File outFile=new File(getFilesDir(),"yoru-wallpaper.jpg");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(outFile)){if(in==null)throw new IOException();byte[] b=new byte[8192];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>24*1024*1024)throw new IOException();out.write(b,0,n);}}YoruApp.app().main.post(()->{wait.dismiss();Ui.toast(this,"Обои готовы. Включите их в внешнем виде.");});}catch(Exception e){YoruApp.app().main.post(()->{wait.dismiss();Ui.toast(this,"Не удалось прочитать изображение");});}});}
    private void aboutDialog(){Ui.message(this,"Это YORU.","Ваше пространство для любимых историй. YORU, календарь выхода, умный просмотр, офлайн, уведомления и минималистичный просмотр.\n\nВерсия "+BuildConfig.VERSION_NAME+"\nМатериалы принадлежат их правообладателям.","Приятного просмотра",null);}
    private String fileName(Uri uri){String name=uri==null?"":uri.getLastPathSegment();if(name==null||name.trim().isEmpty())return "Свой шрифт";int cut=Math.max(name.lastIndexOf('/'),name.lastIndexOf(':'));if(cut>=0&&cut+1<name.length())name=name.substring(cut+1);return name.length()>48?name.substring(name.length()-48):name;}
    private void importFont(Uri uri){Ui.Progress wait=Ui.progress(this,"Импортируем шрифт…",false,null);YoruApp.app().io.execute(()->{try{File outFile=new File(getFilesDir(),"yoru-custom-font.ttf");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(outFile)){if(in==null)throw new IOException();byte[] b=new byte[8192];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>8*1024*1024)throw new IOException();out.write(b,0,n);}}YoruApp.app().store.appearance(YoruApp.app().store.fontScale(),true,fileName(uri));YoruApp.app().main.post(()->{wait.dismiss();Ui.toast(this,"Шрифт применён");render();});}catch(Exception e){YoruApp.app().main.post(()->{wait.dismiss();Ui.toast(this,"Не удалось импортировать шрифт");});}});}
    @Override protected void onPause(){rememberScroll();super.onPause();}
    @Override protected void onSaveInstanceState(Bundle out){rememberScroll();if(search!=null)query=search.getText().toString().trim();out.putInt("tab",tab);out.putBoolean("profile",profileView);out.putString("source",selectedSource);out.putString("query",query);out.putString("bucket",bucket);out.putIntArray("scroll",scrollState);super.onSaveInstanceState(out);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("openDownloads",false)){tab=3;profileView=false;render();}}
    @Override protected void onActivityResult(int request,int code,Intent data){super.onActivityResult(request,code,data);if(request==OfflineExporter.REQ_SAVE_DOCUMENT){OfflineExporter.finishDocumentSave(this,code,data);return;}if(request==OfflineExporter.REQ_SAVE_TREE){OfflineExporter.finishTreeSave(this,code,data);return;}if(code!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==103){importFont(uri);return;}if(request==104){importWallpaper(uri);}}
    @Override public void onBackPressed(){rememberScroll();if(profileView){profileView=false;render();}else if(sourceView){sourceView=false;render();}else if(historyView){historyView=false;render();}else if(tab!=0){tab=0;render();}else super.onBackPressed();}
    @Override protected void onDestroy(){rememberScroll();generation++;if(searchTask!=null)handler.removeCallbacks(searchTask);handler.removeCallbacksAndMessages(null);cancelUiTasks();super.onDestroy();}
